const { EventEmitter } = require("node:events");
const express = require("express");
const app = express()

class WebPanel extends EventEmitter {
    constructor(port, adapter) {
        super(port, adapter)
        this.port = port;
        this.adapter = adapter;

        app.get('/', (req, res) => {
            res.sendStatus(200)
        })
        try {
            app.listen(port, () => {
                this.emit("on")
                console.log(`[CroxyDB]: CroxyDB Web panel is active on http://localhost:${port}`)
            })
        } catch(err) {}
    }
    
}

module.exports = WebPanel;